-- Please note not all available settings / options are set here.
-- For a full list, see the wiki

-- You can split this configuration into multiple files
-- Create your files separately and then link them to this file like this:
-- source = ~/.config/hypr/myColors.conf

-- Load in whatever is the current theme
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

-- Source: ~/.config/current/theme/hyprland.conf — converted to hyprland.lua in the same dir.
-- Prepend the theme dir to package.path so require("hyprland") resolves the theme file,
-- not ./hyprland.lua (this file) which package.path's ./?.lua pattern would otherwise match.
package.path = os.getenv("HOME") .. "/.config/current/theme/?.lua;" .. package.path
require("hyprland")

