--################
--## AUTOSTART ###
--################

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
-- This will make sure that xdg-desktop-portal-hyprland can get the required variables on startup.
-- exec-once = swaync

-- Launch all the web apps we want on startup, they need a little sleep,
-- otherwise they start on differrent workspaces
-- exec-once = [workspace 5 silent] bash -c "sleep 3; exec launch-webapp https://teams.microsoft.com.mcas.ms/v2/"

