hl.on("hyprland.start", function()
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("systemctl --user start xdg-desktop-portal-hyprland")
    hl.exec_cmd("systemctl --user start hyprpolkitagent")
    hl.exec_cmd("/usr/lib/pam_kwallet_init")
    hl.exec_cmd("uwsm app -- elephant")
    hl.exec_cmd("uwsm app -- walker --gapplication-service")
    hl.exec_cmd("uwsm app -- waybar")
    hl.exec_cmd("uwsm app -- hypridle")
    hl.exec_cmd("uwsm app -- swaybg -i ~/.config/current/background -m fill")
    hl.exec_cmd("uwsm app -- mako")
    hl.exec_cmd("uwsm app -- handle-monitor-connect-hyprland")
    hl.exec_cmd("sudo ectool fwchargelimit 70")
    hl.exec_cmd("uwsm app -- brave", { workspace = "1 silent" })
    hl.exec_cmd(terminal, { workspace = "2 silent" })
    hl.exec_cmd("uwsm app -- keepassxc", { workspace = "7 silent" })
    hl.exec_cmd("bash -c \"sleep 3; exec launch-webapp https://web.whatsapp.com/\"", { workspace = "4 silent" })
    hl.exec_cmd("bash -c \"sleep 3; exec launch-webapp https://messenger.com/\"", { workspace = "4 silent" })
    hl.exec_cmd("bash -c \"sleep 3; exec uwsm app -- /opt/teams-for-linux/teams-for-linux --ozone-platform=wayland %U\"", { workspace = "5 silent" })
end)
